def find(prefix):
    """Indices whose display name contains `prefix` (case-insensitive)."""
    p = prefix.upper()
    if not p:
        return list(range(len(NAMES)))
    hits = [i for i, s in enumerate(SHORT) if s.startswith(p)]
    hits += [i for i, s in enumerate(SHORT)
             if p in s and not s.startswith(p)]
    return hits
